import React, { useState, useEffect, useRef } from "react";
import { Link } from "react-router-dom";
import "./Navbar.css";

const Navbar = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false); // Estado para la hamburguesa
  const menuRef = useRef(null); // Referencia al menú para detectar clics fuera de él

  // Detectar scroll para mostrar la navbar fija después del Home
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > window.innerHeight * 0.9) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Detectar clic fuera del menú para cerrarlo
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setIsMenuOpen(false); // Cierra el menú si se hace clic fuera
      }
    };

    document.addEventListener("click", handleClickOutside);

    // Limpiar el evento al desmontar el componente
    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  return (
    <>
      {/* Navbar inicial fusionada con Home */}
      <nav className="navbar navbar-top">
        <div className="navbar-container">
          <h1 className="logo">
            <Link to="/"><span className="trader">FREE</span> TRADER</Link>
          </h1>
          <ul
            className={`nav-links ${isMenuOpen ? "open" : ""}`}
            ref={menuRef} // Referencia al menú para detectar clics fuera
          >
            <li><Link to="/" onClick={() => setIsMenuOpen(false)}>Inicio</Link></li>
            <li><Link to="/cursos" onClick={() => setIsMenuOpen(false)}>Cursos</Link></li>
            <li><Link to="/sobre-nosotros" onClick={() => setIsMenuOpen(false)}>Sobre Nosotros</Link></li>
          </ul>
          {/* Icono de menú hamburguesa */}
          <div className="menu-icon" onClick={() => setIsMenuOpen(!isMenuOpen)}>
            <i className={`fa ${isMenuOpen ? "fa-times" : "fa-bars"}`}></i>
          </div>
        </div>
      </nav>

      {/* Navbar fija que aparece después del Home */}
      <nav className={`navbar navbar-fixed ${isScrolled ? "visible" : ""}`}>
        <div className="navbar-container">
          <h1 className="logo">
            <Link to="/"><span className="trader">FREE</span> TRADER</Link>
          </h1>
          <ul
            className={`nav-links ${isMenuOpen ? "open" : ""}`}
            ref={menuRef} // Referencia al menú para detectar clics fuera
          >
            <li><Link to="/" onClick={() => setIsMenuOpen(false)}>Inicio</Link></li>
            <li><Link to="/cursos" onClick={() => setIsMenuOpen(false)}>Cursos</Link></li>
            <li><Link to="/sobre-nosotros" onClick={() => setIsMenuOpen(false)}>Sobre Nosotros</Link></li>
          </ul>
          {/* Icono de menú hamburguesa */}
          <div className="menu-icon" onClick={() => setIsMenuOpen(!isMenuOpen)}>
            <i className={`fa ${isMenuOpen ? "fa-times" : "fa-bars"}`}></i>
          </div>
        </div>
      </nav>
    </>
  );
};

export default Navbar;
